const body = $input.item.json.body || $input.item.json;
const event = body.event;
const payment = body.payment;

if (!event || !payment) return [{ json: { skip: true, reason: 'Evento ou pagamento ausente' } }];

if (payment.billingType && payment.billingType !== 'CREDIT_CARD') {
  return [{ json: { skip: true, reason: `Billing type não é CREDIT_CARD: ${payment.billingType}` } }];
}

const statusMap = {
  PAYMENT_RECEIVED:            'pago',
  PAYMENT_CONFIRMED:           'pago',
  PAYMENT_OVERDUE:             'atrasado',
  PAYMENT_DELETED:             'cancelado',
  PAYMENT_REFUNDED:            'reembolsado',
  PAYMENT_CHARGEBACK_REQUESTED:'pendente',
  PAYMENT_CHARGEBACK_DISPUTE:  'pendente',
};

const newStatus = statusMap[event];
if (!newStatus) return [{ json: { skip: true, reason: `Evento não tratado: ${event}` } }];

const paymentId = payment.externalReference;
if (!paymentId) return [{ json: { skip: true, reason: 'externalReference ausente' } }];

return [{ json: {
  payment_id: paymentId,
  asaas_id: payment.id,
  event,
  new_status: newStatus,
  paid_at: payment.paymentDate ? new Date(payment.paymentDate).toISOString() : null,
  value: payment.value,
  net_value: payment.netValue,
  card_last_digits: payment.creditCard?.creditCardNumber?.slice(-4) || null,
  card_brand: payment.creditCard?.creditCardBrand || null,
} }];

const data = $input.item.json;
const update = { status: data.new_status };
if (data.paid_at) update.paid_at = data.paid_at;
update.metadata = {
  asaas_id: data.asaas_id,
  card_last_digits: data.card_last_digits,
  card_brand: data.card_brand,
  net_value: data.net_value,
  last_asaas_event: data.event,
  updated_from_asaas_at: new Date().toISOString(),
};
return [{ json: { payment_id: data.payment_id, update } }];
